g.fillStyle(layer%2?p.distant:p.mid,.085+layer*.032);g.beginPath();g.moveTo(-100,720);
for(let x=-100;x<=this.worldWidth+120;x+=step){const wave=Math.sin(x*.0048+layer*1.7)*26+Math.sin(x*.012+layer*2.3)*13+Math.sin(x*.0018+layer)*35;g.lineTo(x,base+wave);}
